nextflow_process {

    name "Test Process KRAKENTOOLS_KREPORT2KRONA"
    script "modules/nf-core/krakentools/kreport2krona/main.nf"
    process "KRAKENTOOLS_KREPORT2KRONA"
    tag "modules"
    tag "modules_nfcore"
    tag "kraken2"
    tag "kraken2/kraken2"
    tag "krakentools"
    tag "krakentools/kreport2krona"

    test("sarscov2 illumina single end [fastq]") {
        def db
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            db = extract(modules_testdata_base_path + 'genomics/sarscov2/genome/db/kraken2.tar.gz').resolve('kraken2')
            run("KRAKEN2_KRAKEN2") {
                script "modules/nf-core/kraken2/kraken2/main.nf"
                process {
                    """
                    input[0] = [
                        [ id:'test', single_end:true ],
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)
                    ]
                    input[1] = file('${db}')
                    input[2] = false
                    input[3] = false
                    """
                }
            }
        }


        when {
            process {
                """
                input[0] = KRAKEN2_KRAKEN2.out.report
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("sarscov2 illumina single end [fastq] - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [ [id: 'test', single_end: true], [] ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}

